order_attribution.validated_operation:
query XOrderAttribution($first: Int!, $after: String, $search: String!) {
  shop { myshopifyDomain }
  orders(first: $first, after: $after, query: $search) {
    nodes {
      id
      createdAt
      test
      cancelledAt
      displayFinancialStatus
      sourceName
      customerJourneySummary {
        ready
        firstVisit { ...XVisit }
        lastVisit { ...XVisit }
        moments(first: 50) {
          nodes { __typename ... on CustomerVisit { ...XVisit } }
          pageInfo { hasNextPage endCursor }
        }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}
fragment XVisit on CustomerVisit {
  occurredAt
  source
  referrerUrl
  landingPage
  utmParameters { source medium campaign content }
}
